up.Cage2_Over.sprite:setAnimation(\"over\") end),\n                Wait(0.05),\n                Do(function() self.scene.objectLookup.Cage2_Over.sprite:setAnimation(\"over_noforcefield\") end),\n                Wait(0.05)\n            }, 10),\n            AudioFade(\"music\", 1, 0, 1)\n        },\n        Wait(1),\n        Animate(sprites.b.sprite, \"idleup\"),\n        Animate(self.scene.objectLookup.UncleT.sprite, \"papat\"),\n        MessageBox{message=\"Tails places {h Translator Collar} on adult Terrapod!\"},\n        Wait(0.5),\n        PlayAudio(\"music\", \"babyt\", 1, true, true),\n        MessageBox{message=\"Terrapod: Be careful, dear nephew! {p60}These mechanical creatures are dangerous!\"},\n        MessageBox{message=\"Terrapod: No offense to your friend here...\"},\n        MessageBox{message=\"B: Oh, {p60}none taken.\"},\n        Parallel {\n            walkin,\n            AudioFade(\"music\", 1, 0, 1)\n        },\n        PlayAudio(\"music\", \"patrol\", 1, true, true)\n    }\n    end\nend"
