p.Cage3_Over.sprite:setAnimation(\"over\") end),\n                Wait(0.05),\n                Do(function() self.scene.objectLookup.Cage3_Over.sprite:setAnimation(\"over_noforcefield\") end),\n                Wait(0.05)\n            }, 10),\n            AudioFade(\"music\", 1, 0, 1)\n        },\n        Wait(1),\n        Animate(sprites.b.sprite, \"idleup\"),\n        Animate(self.scene.objectLookup.GrampaT.sprite, \"grampat\"),\n        MessageBox{message=\"Tails places {h Translator Collar} on adult Terrapod!\"},\n        Wait(0.5),\n        PlayAudio(\"music\", \"babyt\", 1, true, true),\n        MessageBox{message=\"Terrapod: Ahh...{p60} what brave lads you are!\"},\n        MessageBox{message=\"Baby T: *happy grunt*!\"},\n        MessageBox{message=\"Terrapod: Never in all my days did I think I would see a friendly robot! {p60}You remind me of someone...\"},\n        MessageBox{message=\"B: A Swatbot?\"},\n        MessageBox{message=\"Terrapod: Ah, maybe that's it.\"},\n        Parallel {\n            walkin,\n            AudioFade(\"music\", 1, 0, 1)\n        },\n        PlayAudio(\"music\", \"patrol\", 1, true, true)\n    }\n    end\nend"
