"factoryspit\"},\n            Repeat(Serial {\n                Do(function() self.scene.objectLookup.Cage4_Over.sprite:setAnimation(\"over\") end),\n                Wait(0.05),\n                Do(function() self.scene.objectLookup.Cage4_Over.sprite:setAnimation(\"over_noforcefield\") end),\n                Wait(0.05)\n            }, 10),\n            AudioFade(\"music\", 1, 0, 1)\n        },\n        Wait(1),\n        Animate(sprites.b.sprite, \"idleup\"),\n        Animate(self.scene.objectLookup.MamaT.sprite, \"mamat\"),\n        MessageBox{message=\"Tails places {h Translator Collar} on adult Terrapod!\"},\n        Wait(0.5),\n        PlayAudio(\"music\", \"babyt\", 1, true, true),\n        MessageBox{message=\"Mama T: I'm so happy to see you're safe, my child!\"},\n        Do(function() sprites.babyt.sprite.sortOrderY = 1000 end),\n        Parallel {\n            sprites.babyt:hop(),\n            MessageBox{message=\"Baby T: *happy grunt*!\"}\n        },\n        AudioFade(\"music\", 1, 0, 1),\n        Animate(self.scene.objectLookup.MamaT.sprite, \"mamat_sad\"),\n        MessageBox{message=\"Mama T: Tails, {p60}the man you know as {h Robotnik} is\\nhere, {p60}and he's searching for the {h Light of Mobius}...\"},\n        MessageBox{message=\"Mama T: He must be stopped{p60}, before it's too late...\"},\n        MessageBox{message=\"B: Knocking some Swatbots around is one thing... {p80} but facing off against Robotnik himself?...\"},\n        Animate(sprites.b.sprite, \"pose\"),\n        MessageBox{message=\"B: Maybe we should just wait for the real Freedom Fighters to show up...\"},\n        MessageBox{message=\"Mama T: Time is of the essence. {p60}Robotnik is already nearing the {h Cave of Light}, {p60}the sacred temple.\"},\n        Animate(sprites.b.sprite, \"idleup\"),\n        MessageBox{message=\"B: What will happen if Robotnik gets to this \\\"Light\\\" before we do? {p80}What exactly is this\\n\\\"Light of Mobius\\\"?\"},\n        PlayAudio(\"music\", \"lightofmobius\", 1, true, true),\n        Animate(self.scene.objectLookup.MamaT.sprite, \"mamat\"),\n        MessageBox{message=\"Mama T: The Light has existed since the dawn of Mobius... {p80}it's said that the Light is made from the hopes and dreams of all living beings...\"},\n        MessageBox{message=\"Mama T: As you approach the Light, you will be granted one wish... {p80}and although the Light naturally resists evil wishes that seek death, displacement, or power over others, we know that Robotnik is cunning--\"},\n        Animate(self.scene.objectLookup.MamaT.sprite, \"mamat_sad\"),\n        MessageBox{message=\"Mama T: He has undoubtedly found a way to still use the Light's power to serve his dark ambitions...\"},\n        Animate(self.scene.objectLookup.MamaT.sprite, \"mamat\"),\n        MessageBox{message=\"Mama T: Take this with you, {p60}this will reveal the secret entrance to the {h Cave of Light}...\"},\n        MessageBox{message=\"Mama T gives Tails {h Rainbow Conk Shell}!\", sfx=\"levelup\"},\n        -- Shadow passes overhead\n        Do(function()\n            shadowLayer.opacity = 0.6\n        end),\n        Parallel {\n            AudioFade(\"music\", 1, 0, 1),\n            Ease(shadowLayer, \"offsety\", 300, 0.1),\n            Serial {\n                Wait(3),\n                PlayAudio(\"sfx\", \"elevator\", 1, true),\n                Wait(1),\n                Do(function()\n                    sprites.b.sprite.sortOrderY = 1000\n                    sprites.tails.sprite.sortOrderY = 1000\n                end),\n                Animate(sprites.b.sprite, \"shock\"),\n                Animate(sprites.babyt.sprite, \"shock\"),\n                Animate(sprites.tails.sprite, \"shock\"),\n                Parallel {\n                    MessageBox{message=\"Tails: What's going on?!\", closeAction=Wait(1)},\n                    sprites.b:hop(),\n                    sprites.babyt:hop(),\n                    sprites.tails:hop(),\n                },\n                PlayAudio(\"music\", \"robotnikship\", 1, true),\n                Animate(self.scene.objectLookup.MamaT.sprite, \"mamat_sad\"),\n                MessageBox{message=\"Mama T: Robotnik!\", closeAction=Wait(2)},\n\n                Do(function()\n                    GameState:grantItem(require \"data/items/RainbowConkShell\", 1)\n                    self.scene:changeScene{map=\"boulderbay_meanwhile2\", fadeOutSpeed=2, fadeInSpeed=0.5}\n                end)\n            }\n        }\n    }\n    end\nend"
